'use strict';

var Errors = {};

Errors.MissingArgumentError = function(contextName, argumentName) {
    this.message = 'The following argument is required for the `'+ contextName +'` function: '+ argumentName;
};

Errors.InvalidArgumentError = function(contextName, argumentName, errorLabel) {
    this.message = 'The '+ argumentName +' argument is invalid for the `'+ contextName +'` function: '+ errorLabel;
};

Errors.APIError = {
    MISSING_ACCESS_KEY: 101,
    INVALID_ACCESS_KEY: 101,
    INVALID_API_FUNCTION: 103,
    USAGE_LIMIT_REACHED: 104,
    HTTPS_ACCESS_RESTRICTED: 105,
    FUNCTION_ACCESS_RESTRICTED: 106,
    INACTIVE_USER: 102,
    QUERY_TEXT_IS_ARRAY: 211,
    QUERY_TEXT_NO_ARRAY: 212,
    TOO_MANY_QUERIES: 221,
    DETECTION_FAILED: 910,
    BATCH_DETECTION_FAILED: 911,
    NO_QUERY_TEXT_PROVIDED: 210,
    '404_NOT_FOUND': 404
};

/**
 * Exports ResultStatus
 * @type {Function}
 */
module.exports = Errors;

'use strict';

var _ = require('lodash');
var Transporter = require('./transporter');
var APIResult = require('./apirequest-result');


var APIRequest = {};


/**
 * Create and send request to DetectLanguage API
 * @param  {object}   parameters Parameters used to form request
 * @param  {Function} callback   Callback when request finished or error found
 * @return {Request}             Returns Request object or null
 */
var requestFn = function (parameters, callback) {


    // For demo purposes we enable being able to use the publicly available key, and if so, we use the reserved demo gateway
    if (parameters.options.access_key == '[SECRET_KEY]') {

        if (parameters.options.service != 'detect') {
            return callback(new Error('Only Detect is supported for this account'));
        }

        parameters.options.secure = true;
        parameters.options.host = 'languagelayer.com';
        parameters.options.context = 'php_helper_scripts';
        parameters.options.service = 'language_api.php';
        parameters.options.key_type = 'secret_key';
        parameters.options.access_key = 'aab530f2dd1856e238a7c9875ca3876c';
    }


    var url = parameters.options.secure ? 'https' : 'http';
    url += '://';
    url += parameters.options.host;
    url += '/';
    url += parameters.options.context;
    url += '/';
    url += parameters.options.service;
    url += '?' + parameters.options.key_type + '=' + parameters.options.access_key;

    parameters.options.url = url;


    var req = new Transporter(parameters.options).request(parameters.params, function (err, result) {

        if (err) {
            return callback(err);
        }
        else if (result.statusCode != APIResult.OK || !_.get(result, APIResult.BODY_SUCCESS_EXPR)) {
            err = _.get(result, APIResult.BODY_ERROR_EXPR);
            return callback(err);
        }

        return callback(null, result);
    });
    return req;
};
APIRequest.request = requestFn;


/**
 * Exports APIRequest
 * @type {Function}
 */
module.exports = APIRequest;

'use strict';

var ResultStatus = {};

ResultStatus.OK = 200;

ResultStatus.BODY_RESULTS_EXPR = 'body.results';
ResultStatus.BODY_LANGUAGES_EXPR = 'body.languages';
ResultStatus.BODY_SUCCESS_EXPR = 'body.success';
ResultStatus.BODY_ERROR_EXPR = 'body.error';

/**
 * Exports ResultStatus
 * @type {Function}
 */
module.exports = ResultStatus;

'use strict';

var utils = require('../lib/utils');
var Promise = require('../lib/promise');
var APIResult = require('../lib/apirequest-result');
var APIError = require('../lib/apirequest-error');


// Declare our main module scope
var API = {};


/**
 * Detect Language from String
 *
 * @param  {object} params - Parameters for request
 * @param  {callback} callback - The callback that handles the response.
 * @return {object} Result
 */
API.detect = function (params, callback, options) {


    options = utils.defaults({}, options, this.options, {
            service: 'detect',
            method: 'GET'
        }
    );


    // Declare the promise we will use to wrap the request call
    var promise = new Promise(function (resolve, reject) {


        // Input Validation (we only do the most basic, and let the server do the most so validation will always be up to date)
        if (!params) {
            return reject(new APIError.MissingArgumentError('detect', 'params'));
        }


        // URI Encoding of the Query as per recommendation, and ensuring we are working on a new instance of the params
        if (params.query && utils.isString(params.query)) {
            params = utils.extend({}, params, {
                query: encodeURIComponent(params.query)
            });
        }


        // Prepare Parameters and prepare it for the Request modus
        params = {
            options: options,
            params: {
                json: true,
                qs: params
            }
        };


        var APIRequest = require('../lib/apirequest');
        APIRequest.request(params, function (err, result) {

            // If an error happens, we return early
            if (err) {
                return reject(err);
            }

            // parse the results to make the caller only get the actual data and hide the transport information
            result = utils.get(result, APIResult.BODY_RESULTS_EXPR);

            // and we resolve and return (not necessary to return, but keeps consistency)
            return resolve(result);
        });
    });


    // Ensure callback is set to make the main functions slightly simpler by avoiding nested conditionals
    callback = callback || utils.noop;

    // We offer callback support in addition to promise style (we know callback is set as we default it in the beginning)
    promise
        .then(function (result) {
            callback(null, result);
        })
        .catch(function (err) {
            callback(err);
        });


    // return the promise to the caller
    return promise;
};


/**
 * Exports the APIs
 * @type {Object}
 */
module.exports = API;

